function navigate(path){const destination=path.split('/').filter(Boolean)[0],fromApplication=Boolean(applications[current().app]),toApplication=Boolean(applications[destination]),openingApplication=toApplication&&(!fromApplication||destination!==current().app),leavingApplication=fromApplication&&!toApplication,pageChange=toApplication&&!openingApplication&&path!==location.pathname;clearTimeout(applicationLoadingTimer);clearTimeout(componentSkeletonTimer);componentSkeletonLoading=false;if(openingApplication){if(!document.body.classList.contains('rail-hidden'))sessionStorage.setItem('hub-rail-mode-before-app',['expanded','collapsed','hidden'].find(mode=>document.body.classList.contains(`rail-${mode}`))||localStorage.getItem('hub-rail-mode')||'collapsed');setRailMode('hidden')}else if(leavingApplication){const previousMode=sessionStorage.getItem('hub-rail-mode-before-app');if(previousMode)setRailMode(previousMode);sessionStorage.removeItem('hub-rail-mode-before-app')}history.pushState({},'',path);applicationLoading=openingApplication;componentSkeletonLoading=pageChange;render();window.scrollTo(0,0);if(openingApplication)applicationLoadingTimer=setTimeout(()=>{applicationLoading=false;componentSkeletonLoading=true;render();componentSkeletonTimer=setTimeout(()=>{componentSkeletonLoading=false;render()},900)},3500);else if(pageChange)componentSkeletonTimer=setTimeout(()=>{componentSkeletonLoading=false;render()},700)}
