function activity(ico,title,detail,time,bg,color){return`<div class="activity-row"><span class="activity-icon" style="background:${bg};color:${color}">${svg(ico)}</span><div class="activity-text"><strong>${title}</strong><br>${detail}</div><span class="activity-time">${time}</span></div>`}
