function startApplicationLoader(){const container=document.querySelector('.app-loading');if(!container)return;const percentage=container.querySelector('.loader-percentage'),fill=container.querySelector('.loader-fill');const start=performance.now();function tick(now){if(!container.isConnected||!applicationLoading)return;const ratio=Math.min((now-start)/3500,1),eased=1-Math.pow(1-ratio,2.2),value=Math.floor(eased*100);percentage.textContent=`${value}%`;fill.style.width=`${value}%`;if(ratio<1){requestAnimationFrame(tick)}else{percentage.textContent='100%';fill.style.width='100%'}}requestAnimationFrame(tick)}
