function modal(type){const labels={request:['Nova solicitação','Descreva o que você precisa e enviaremos para aprovação.',['Título da solicitação','Categoria','Descrição']],asset:['Cadastrar ativo','Adicione um equipamento ao inventário da organização.',['Nome do ativo','Categoria','Responsável']],indicator:['Novo indicador','Cadastre um indicador para acompanhar os resultados.',['Nome do indicador','Área responsável','Meta']]};const [title,copy,fields]=labels[type]||labels.request;const fieldsHtml=fields.map((f,i)=>`<div class="form-field"><label>${f}</label>${i===1?'<select><option>Selecione uma opção</option><option>Tecnologia</option><option>Equipamentos</option><option>Software</option><option>Operações</option></select>':i===2?'<textarea placeholder="Adicione detalhes..."></textarea>':'<input placeholder="Digite aqui..." required />'}</div>`).join('');const host=document.createElement('div');host.className='overlay';host.innerHTML=`<section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div class="modal-header"><h2 id="modal-title">${title}</h2><button class="modal-close" aria-label="Fechar">×</button></div><p class="modal-copy">${copy}</p><form>${fieldsHtml}<div class="modal-actions"><button type="button" class="secondary-button modal-cancel">Cancelar</button><button type="submit" class="primary-button">Enviar solicitação</button></div></form></section>`;document.body.append(host);const close=()=>host.remove();host.querySelector('.modal-close').onclick=close;host.querySelector('.modal-cancel').onclick=close;host.addEventListener('click',e=>{if(e.target===host)close()});host.querySelector('form').onsubmit=e=>{e.preventDefault();close();toast(type==='asset'?'Ativo cadastrado com sucesso.':type==='indicator'?'Indicador criado com sucesso.':'Solicitação enviada para aprovação.')};host.querySelector('input')?.focus()}
