document.addEventListener('click',e=>{const railToggle=e.target.closest('[data-rail-toggle]');if(railToggle){e.preventDefault();const menu=document.querySelector(`[data-rail-submenu="${railToggle.dataset.railToggle}"]`);if(menu){const willOpen=!menu.classList.contains('open');menu.classList.toggle('open',willOpen);railToggle.setAttribute('aria-expanded',String(willOpen))}return}const filterBtn=e.target.closest('[data-audit-filter],[data-env-filter]');if(filterBtn){e.preventDefault();if(filterBtn.dataset.auditFilter!==undefined)state.auditFilter=filterBtn.dataset.auditFilter;else if(filterBtn.dataset.envFilter!==undefined)state.envFilter=filterBtn.dataset.envFilter;render();return}const revealBtn=e.target.closest('[data-env-reveal]');if(revealBtn){e.preventDefault();const key=revealBtn.dataset.envReveal;state.revealedEnv=state.revealedEnv||new Set();if(state.revealedEnv.has(key))state.revealedEnv.delete(key);else state.revealedEnv.add(key);render();return}const roleToggle=e.target.closest('[data-role-toggle]');if(roleToggle){e.preventDefault();const card=roleToggle.closest('.role-card');const willOpen=!card.classList.contains('open');card.classList.toggle('open',willOpen);roleToggle.setAttribute('aria-expanded',String(willOpen));return}const menuBtn=e.target.closest('[data-row-menu]');if(menuBtn){e.preventDefault();e.stopPropagation();const key=menuBtn.dataset.rowMenu;const existingMenu=document.querySelector('.row-menu');if(existingMenu&&existingMenu.dataset.forKey===key){closeRowMenu();return}const[scope,encoded]=key.split(':'),label=scope==='env'?'variável':scope==='role'?'função':'serviço';openRowMenu(menuBtn,[{label:`Editar ${label}`,action:`edit:${scope}:${encoded}`},{label:`Excluir ${label}`,action:`delete:${scope}:${encoded}`,danger:true}]);return}const rowActionBtn=e.target.closest('.row-menu [data-row-action]');if(rowActionBtn){e.preventDefault();handleRowAction(rowActionBtn.dataset.rowAction);closeRowMenu();return}const addBtn=e.target.closest('[data-admin-add]');if(addBtn){e.preventDefault();openAdminModal(addBtn.dataset.adminAdd,null);return}if(!e.target.closest('.row-menu')&&!e.target.closest('[data-row-menu]'))closeRowMenu();const route=e.target.closest('[data-route]');if(route){e.preventDefault();navigate(route.dataset.route);return}const modalBtn=e.target.closest('[data-modal]');if(modalBtn){modal(modalBtn.dataset.modal);return}const toastBtn=e.target.closest('[data-toast]');if(toastBtn){toast(toastBtn.dataset.toast);return}if(e.target.closest('[data-mobile-menu]')){document.getElementById('workspace')?.classList.add('menu-open');return}if(e.target.closest('[data-mobile-close]')){document.getElementById('workspace')?.classList.remove('menu-open');return}if(e.target.closest('#notifications-button')){const pop=document.getElementById('header-popover');pop.classList.toggle('hidden');pop.innerHTML='<h3>Notificações</h3><div class="popover-row"><strong>Deploy concluído</strong><small>Gestão de Ativos · há 12 minutos</small></div><div class="popover-row"><strong>Nova solicitação para aprovar</strong><small>Solicitações · há 1 hora</small></div>';return}if(!e.target.closest('.header-popover'))document.getElementById('header-popover').classList.add('hidden')});
window.addEventListener('popstate',()=>{applicationLoading=false;componentSkeletonLoading=false;clearTimeout(applicationLoadingTimer);clearTimeout(componentSkeletonTimer);render()});const search=document.getElementById('global-search'),results=document.getElementById('search-results');const searchable=[...Object.entries(applications).flatMap(([key,a])=>[[a.name,`/${key}`,a.description],...a.sections.map(([id,name])=>[`${name} · ${a.name}`,`/${key}/${id}`,`Página da aplicação ${a.name}`])]),['Página inicial','/','Dashboard da plataforma'],['Aplicações','/applications','Catálogo de aplicações']];search.addEventListener('input',()=>{const q=search.value.trim().toLowerCase();if(!q){results.classList.add('hidden');return}const found=searchable.filter(([name,,desc])=>(name+' '+desc).toLowerCase().includes(q)).slice(0,6);results.innerHTML=found.length?found.map(([name,path,desc])=>`<button class="search-result" data-search-route="${path}">${iconSquare(applications[path.split('/')[1]]||{color:'#f0edff',ink:'#654de1',icon:'grid'})}<span>${name}<small>${desc}</small></span></button>`).join(''):'<div class="search-result">Nenhum resultado encontrado</div>';results.classList.remove('hidden')});results.addEventListener('click',e=>{const btn=e.target.closest('[data-search-route]');if(btn){navigate(btn.dataset.searchRoute);search.value='';results.classList.add('hidden')}});document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();search.focus()}if(e.key==='Escape'){results.classList.add('hidden');document.getElementById('header-popover').classList.add('hidden');document.querySelector('.overlay')?.remove();document.getElementById('workspace')?.classList.remove('menu-open');closeRowMenu()}});document.addEventListener('change',e=>{const permBox=e.target.closest('[data-role-perm]');if(permBox){const[encodedName,idxStr]=permBox.dataset.rolePerm.split(':'),name=decodeURIComponent(encodedName),role=rolesData.find(r=>r[0]===name);if(role){role[4][Number(idxStr)]=permBox.checked?1:0;saveCache('roles',rolesData)}}});render();
